    expect(trapFocus(dialog, press('Escape'))).toBe(false)
    expect(trapFocus(dialog, press('Enter'))).toBe(false)
    expect(trapFocus(document.createElement('div'), press('Tab'))).toBe(false)
    expect(trapFocus(null, press('Tab'))).toBe(false)
  })
